/*
 * Strict C11 NFL1 v1 codec KATs (ADR-0017 / docs/34 §5).
 * Known-answer bytes hardcoded from accepted
 * spec/vectors/fabric-bearer-spec-v1.json (independent of production codec).
 * Caller-owned fixed buffers only. No heap/VLA.
 */
#include "nfl1_codec.h"

#include <stdio.h>
#include <string.h>

static int g_fail;

#define REQUIRE(cond)                                                       \
    do {                                                                    \
        if (!(cond)) {                                                      \
            (void)fprintf(stderr, "FAIL %s:%d: %s\n", __FILE__, __LINE__,   \
                #cond);                                                     \
            g_fail++;                                                       \
            return 1;                                                       \
        }                                                                   \
    } while (0)

#define REQUIRE_EQ_U32(a, b)                                                \
    do {                                                                    \
        uint32_t _a = (uint32_t)(a);                                        \
        uint32_t _b = (uint32_t)(b);                                        \
        if (_a != _b) {                                                     \
            (void)fprintf(stderr,                                           \
                "FAIL %s:%d: %s (%u) != %s (%u)\n", __FILE__, __LINE__,     \
                #a, (unsigned)_a, #b, (unsigned)_b);                        \
            g_fail++;                                                       \
            return 1;                                                       \
        }                                                                   \
    } while (0)

static int pointer_outside_range(
    const void *pointer, const void *range_begin, uint32_t range_length)
{
    uintptr_t address = (uintptr_t)pointer;
    uintptr_t begin = (uintptr_t)range_begin;

    return address < begin || address - begin >= (uintptr_t)range_length;
}

static uint32_t sha256_rotr(uint32_t v, unsigned b)
{
    return (v >> b) | (v << (32u - b));
}

static void sha256(const uint8_t *msg, size_t len, uint8_t out[32])
{
    static const uint32_t k[64] = {
        0x428a2f98u, 0x71374491u, 0xb5c0fbcfu, 0xe9b5dba5u, 0x3956c25bu,
        0x59f111f1u, 0x923f82a4u, 0xab1c5ed5u, 0xd807aa98u, 0x12835b01u,
        0x243185beu, 0x550c7dc3u, 0x72be5d74u, 0x80deb1feu, 0x9bdc06a7u,
        0xc19bf174u, 0xe49b69c1u, 0xefbe4786u, 0x0fc19dc6u, 0x240ca1ccu,
        0x2de92c6fu, 0x4a7484aau, 0x5cb0a9dcu, 0x76f988dau, 0x983e5152u,
        0xa831c66du, 0xb00327c8u, 0xbf597fc7u, 0xc6e00bf3u, 0xd5a79147u,
        0x06ca6351u, 0x14292967u, 0x27b70a85u, 0x2e1b2138u, 0x4d2c6dfcu,
        0x53380d13u, 0x650a7354u, 0x766a0abbu, 0x81c2c92eu, 0x92722c85u,
        0xa2bfe8a1u, 0xa81a664bu, 0xc24b8b70u, 0xc76c51a3u, 0xd192e819u,
        0xd6990624u, 0xf40e3585u, 0x106aa070u, 0x19a4c116u, 0x1e376c08u,
        0x2748774cu, 0x34b0bcb5u, 0x391c0cb3u, 0x4ed8aa4au, 0x5b9cca4fu,
        0x682e6ff3u, 0x748f82eeu, 0x78a5636fu, 0x84c87814u, 0x8cc70208u,
        0x90befffau, 0xa4506cebu, 0xbef9a3f7u, 0xc67178f2u
    };
    uint32_t h[8] = {
        0x6a09e667u, 0xbb67ae85u, 0x3c6ef372u, 0xa54ff53au,
        0x510e527fu, 0x9b05688cu, 0x1f83d9abu, 0x5be0cd19u
    };
    uint8_t block[64];
    uint64_t bit_len = (uint64_t)len * 8u;
    size_t offset = 0u, remain = len;
    int done = 0;
    while (!done) {
        size_t i, take = remain > 64u ? 64u : remain;
        uint32_t w[64], a, b, c, d, e, f, g, hh;
        (void)memset(block, 0, sizeof(block));
        if (take > 0u) {
            (void)memcpy(block, msg + offset, take);
            offset += take;
            remain -= take;
        }
        if (take < 64u) {
            block[take] = 0x80u;
            if (take < 56u) {
                for (i = 0u; i < 8u; ++i) {
                    block[63u - i] = (uint8_t)(bit_len >> (8u * i));
                }
                done = 1;
            }
        }
        for (i = 0u; i < 16u; ++i) {
            w[i] = ((uint32_t)block[i * 4u] << 24)
                | ((uint32_t)block[i * 4u + 1u] << 16)
                | ((uint32_t)block[i * 4u + 2u] << 8)
                | (uint32_t)block[i * 4u + 3u];
        }
        for (i = 16u; i < 64u; ++i) {
            uint32_t s0 = sha256_rotr(w[i - 15u], 7u)
                ^ sha256_rotr(w[i - 15u], 18u) ^ (w[i - 15u] >> 3);
            uint32_t s1 = sha256_rotr(w[i - 2u], 17u)
                ^ sha256_rotr(w[i - 2u], 19u) ^ (w[i - 2u] >> 10);
            w[i] = w[i - 16u] + s0 + w[i - 7u] + s1;
        }
        a = h[0]; b = h[1]; c = h[2]; d = h[3];
        e = h[4]; f = h[5]; g = h[6]; hh = h[7];
        for (i = 0u; i < 64u; ++i) {
            uint32_t S1 = sha256_rotr(e, 6u) ^ sha256_rotr(e, 11u)
                ^ sha256_rotr(e, 25u);
            uint32_t ch = (e & f) ^ ((~e) & g);
            uint32_t t1 = hh + S1 + ch + k[i] + w[i];
            uint32_t S0 = sha256_rotr(a, 2u) ^ sha256_rotr(a, 13u)
                ^ sha256_rotr(a, 22u);
            uint32_t maj = (a & b) ^ (a & c) ^ (b & c);
            uint32_t t2 = S0 + maj;
            hh = g; g = f; f = e; e = d + t1;
            d = c; c = b; b = a; a = t1 + t2;
        }
        h[0] += a; h[1] += b; h[2] += c; h[3] += d;
        h[4] += e; h[5] += f; h[6] += g; h[7] += hh;
    }
    {
        size_t i;
        for (i = 0u; i < 8u; ++i) {
            out[i * 4u] = (uint8_t)(h[i] >> 24);
            out[i * 4u + 1u] = (uint8_t)(h[i] >> 16);
            out[i * 4u + 2u] = (uint8_t)(h[i] >> 8);
            out[i * 4u + 3u] = (uint8_t)h[i];
        }
    }
}

static int hex_eq32(const uint8_t dig[32], const char *hex)
{
    size_t i;
    for (i = 0u; i < 32u; ++i) {
        unsigned int hi, lo;
        char c0 = hex[i * 2u];
        char c1 = hex[i * 2u + 1u];
        hi = (unsigned)(c0 >= 'a' ? c0 - 'a' + 10 : c0 - '0');
        lo = (unsigned)(c1 >= 'a' ? c1 - 'a' + 10 : c1 - '0');
        if (dig[i] != (uint8_t)((hi << 4) | lo)) {
            return 0;
        }
    }
    return 1;
}


