static int test_kat_k_app_min(void)
{
    ninlil_fabric_private_nfl1_workspace_t ws;
    ninlil_fabric_private_nfl1_envelope_t env;
    uint8_t dig[32];
    uint32_t required = 0u;
    uint32_t crc;
    uint8_t marker[8];
    (void)memset(&ws, 0xA5, sizeof(ws));
    (void)memset(marker, 0xA5, sizeof(marker));
    (void)memset(&env, 0x5A, sizeof(env));
    REQUIRE_EQ_U32(
        ninlil_fabric_private_nfl1_decode(
            k_app_min, k_app_min_len, &ws, &env, &required),
        NINLIL_FABRIC_PRIVATE_NFL1_OK);
    REQUIRE_EQ_U32(env.message_kind, 1u);
    REQUIRE(env.namespace_id.bytes != NULL);
    REQUIRE(env.namespace_id.bytes >= ws.bytes);
    REQUIRE(env.namespace_id.bytes < ws.bytes + sizeof(ws.bytes));
    /* no retained pointer into input packet */
    REQUIRE(pointer_outside_range(
        env.namespace_id.bytes, k_app_min, k_app_min_len));
    crc = ninlil_fabric_private_nfl1_crc32c(k_app_min, k_app_min_len);
    /* stored CRC field must match independent recomputation with zeroed field */
    {
        uint8_t tmp[NINLIL_FABRIC_PRIVATE_NFL1_CODEC_CEILING];
        uint32_t stored;
        (void)memcpy(tmp, k_app_min, k_app_min_len);
        stored = ((uint32_t)tmp[12] << 24) | ((uint32_t)tmp[13] << 16)
            | ((uint32_t)tmp[14] << 8) | (uint32_t)tmp[15];
        tmp[12] = tmp[13] = tmp[14] = tmp[15] = 0u;
        REQUIRE_EQ_U32(
            ninlil_fabric_private_nfl1_crc32c(tmp, k_app_min_len), stored);
        REQUIRE(stored == 0xe61981b1u);
        (void)crc;
    }
    sha256(k_app_min, k_app_min_len, dig);
    REQUIRE(hex_eq32(dig, "c11c9ee6a0b4fd470ec2ea15555c5797b1224c511b350184286fcacbcf38d839"));
    ninlil_fabric_private_nfl1_clear(&env);
    REQUIRE(env.message_kind == 0u);
    REQUIRE(env.namespace_id.bytes == NULL);
    return 0;
}

